import { usersApi } from '../../api/services';
import { ROLES } from '../../auth/permissions';
import { useAsync } from '../../hooks/useAsync';
import { toNumber, useForm } from '../../hooks/useForm';
import { centsToDollars, dollarsToCents, emailRuleHint, label } from '../../utils/format';
import { Alert } from '../Feedback';
import FormField from '../FormField';
import { Modal } from '../Modal';

/**
 * Admin form to create or edit any user. The employee ID and password are
 * generated by the server on creation.
 *
 * @param {{user?: object, currentUserId: number, onSave: Function, onClose: Function}} props
 */
export default function UserForm({ user, currentUserId, onSave, onClose }) {
  const editing = Boolean(user);
  const isSelf = editing && user.id === currentUserId;
  const { data: people } = useAsync(() => usersApi.list({ is_active: 'true', page_size: 100, sort: 'name' }), 'managers');
  const managers = (people?.items || []).filter((p) => p.role !== 'employee' && p.id !== user?.id);

  const { values, bind, errors, formError, busy, handleSubmit } = useForm({
    first_name: user?.first_name || '',
    last_name: user?.last_name || '',
    email: user?.email || '',
    job_title: user?.job_title || '',
    salary: centsToDollars(user?.salary_cents ?? null),
    role: user?.role || 'employee',
    manager_id: user?.manager_id ?? '',
    is_active: user?.is_active ?? true,
  });

  const submit = handleSubmit(async (v) => {
    const body = {
      first_name: v.first_name,
      last_name: v.last_name,
      email: v.email,
      job_title: v.job_title,
      salary_cents: dollarsToCents(v.salary),
      role: v.role,
      manager_id: toNumber(v.manager_id),
    };
    if (isSelf) {
      delete body.role;
      delete body.salary_cents;
    } else if (editing) {
      body.is_active = Boolean(v.is_active);
    }
    await onSave(body);
  });

  return (
    <Modal
      title={editing ? `Edit ${user.full_name}` : 'New user'}
      onClose={onClose}
      size="lg"
      footer={(
        <>
          <button type="button" className="btn btn-ghost" onClick={onClose}>Cancel</button>
          <button type="submit" form="user-form" className="btn btn-primary" disabled={busy}>
            {busy ? 'Saving…' : editing ? 'Save changes' : 'Create user'}
          </button>
        </>
      )}
    >
      <form id="user-form" className="form-grid" onSubmit={submit} noValidate>
        {!editing && (
          <p className="muted span-all">An employee ID and a 6-character password will be generated. You will see them once, after saving.</p>
        )}
        {formError && <div className="span-all"><Alert kind="error">{formError}</Alert></div>}
        <FormField label="First name" required error={errors.first_name}>
          <input {...bind('first_name')} maxLength={100} autoComplete="off" />
        </FormField>
        <FormField label="Last name" required error={errors.last_name}>
          <input {...bind('last_name')} maxLength={100} autoComplete="off" />
        </FormField>
        <FormField label="Email" required error={errors.email} hint={emailRuleHint(values.first_name, values.last_name)}>
          <input type="email" {...bind('email')} autoComplete="off" />
        </FormField>
        <FormField label="Job title" required error={errors.job_title}>
          <input {...bind('job_title')} maxLength={150} />
        </FormField>
        <FormField label="Role" required error={errors.role} hint={isSelf ? 'Nobody can change their own role.' : undefined}>
          <select {...bind('role')} disabled={isSelf}>
            {ROLES.map((r) => <option key={r} value={r}>{label(r)}</option>)}
          </select>
        </FormField>
        <FormField label="Manager" error={errors.manager_id} hint="Each person reports to one manager.">
          <select {...bind('manager_id')}>
            <option value="">No manager</option>
            {managers.map((m) => <option key={m.id} value={m.id}>{m.full_name} ({label(m.role)})</option>)}
          </select>
        </FormField>
        <FormField label="Annual salary (USD)" error={errors.salary_cents}
          hint={isSelf ? 'Nobody can change their own salary.' : 'Hourly rate = salary ÷ 2080'}>
          <input type="number" min="0" step="0.01" inputMode="decimal" {...bind('salary')} disabled={isSelf} />
        </FormField>
        {editing && !isSelf && (
          <div className="field checkbox-field">
            <label>
              <input type="checkbox" {...bind('is_active')} checked={Boolean(bind('is_active').value)} />
              Active (can sign in)
            </label>
            {errors.is_active && <p className="field-error">{errors.is_active}</p>}
          </div>
        )}
      </form>
    </Modal>
  );
}
